import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Trend, Counter } from 'k6/metrics';
import { API_URL, authHeaders } from './k6.config.js';

/**
 * BUSINESS FLOW TEST — Simulates complete user journeys
 * Tests the full order lifecycle under load
 * VUs: 30 | Duration: 5 minutes
 */

const flowDuration = new Trend('business_flow_duration', true);
const flowsCompleted = new Counter('business_flows_completed');
const flowsFailed = new Counter('business_flows_failed');

export const options = {
  stages: [
    { duration: '30s', target: 15 },
    { duration: '4m', target: 30 },
    { duration: '30s', target: 0 },
  ],
  thresholds: {
    business_flow_duration: ['p(95)<3000'],  // Full flow < 3 seconds
    http_req_failed: ['rate<0.01'],
  },
  tags: { test_type: 'business_flow' },
};

export default function () {
  const flowStart = Date.now();
  let success = true;

  group('Complete Order Flow', () => {
    // ── Step 1: Client creates order ──
    let orderId;
    {
      const res = http.post(
        `${API_URL}/orders`,
        JSON.stringify({
          title: `Flow Test ${Date.now()}`,
          description: 'Business flow load test order',
          eventType: 'corporate',
          eventDate: '2026-12-15T10:00:00Z',
          estimatedBudget: { amount: 80000, currency: 'MXN' },
          guestCount: 200,
          urgency: 'normal',
        }),
        { headers: authHeaders('client') },
      );

      if (res.status !== 201) { success = false; return; }
      try {
        orderId = JSON.parse(res.body).data.orderId;
      } catch { success = false; return; }

      check(res, { 'step1: order created': res.status === 201 });
    }

    sleep(0.3);

    // ── Step 2: Verify order exists ──
    {
      const res = http.get(`${API_URL}/orders/${orderId}`, {
        headers: authHeaders('client'),
      });

      check(res, { 'step2: order readable': res.status === 200 });
      if (res.status !== 200) { success = false; return; }
    }

    sleep(0.3);

    // ── Step 3: Admin assigns provider ──
    {
      const res = http.post(
        `${API_URL}/orders/${orderId}/assign-provider`,
        JSON.stringify({ providerId: __ENV.PROVIDER_ID || 'test-provider-id' }),
        { headers: authHeaders('admin') },
      );

      check(res, { 'step3: provider assigned': res.status === 200 });
      if (res.status !== 200) { success = false; return; }
    }

    sleep(0.3);

    // ── Step 4: Verify state changed ──
    {
      const res = http.get(`${API_URL}/orders/${orderId}`, {
        headers: authHeaders('admin'),
      });

      if (res.status === 200) {
        try {
          const body = JSON.parse(res.body);
          check(res, {
            'step4: state is assigned': body.data?.state === 'assigned',
          });
        } catch { /* ignore */ }
      }
    }

    sleep(0.3);

    // ── Step 5: Provider creates quotation ──
    let quotationId;
    {
      const res = http.post(
        `${API_URL}/quotations`,
        JSON.stringify({
          orderId: orderId,
          items: [
            { description: 'Sound System', quantity: 1, unitCost: 25000 },
            { description: 'Lighting', quantity: 1, unitCost: 15000 },
            { description: 'Stage', quantity: 1, unitCost: 10000 },
          ],
          notes: 'Load test quotation',
        }),
        { headers: authHeaders('provider') },
      );

      if (res.status === 201) {
        try {
          quotationId = JSON.parse(res.body).data.quotationId;
        } catch { /* ignore */ }
      }
      check(res, { 'step5: quotation created': res.status === 201 });
    }

    sleep(0.3);

    // ── Step 6: List orders (verify in lists) ──
    {
      const res = http.get(`${API_URL}/orders?page=1&limit=10`, {
        headers: authHeaders('client'),
      });
      check(res, { 'step6: list accessible': res.status === 200 });
    }

    sleep(0.3);

    // ── Step 7: Admin dashboard (verify stats updated) ──
    {
      const res = http.get(`${API_URL}/admin/dashboard`, {
        headers: authHeaders('admin'),
      });
      check(res, { 'step7: dashboard loaded': res.status === 200 });
    }
  });

  const flowMs = Date.now() - flowStart;
  flowDuration.add(flowMs);

  if (success) {
    flowsCompleted.add(1);
  } else {
    flowsFailed.add(1);
  }

  sleep(Math.random() * 2 + 1);
}

import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import {
  API_URL,
  authHeaders,
  checkResponse,
  STANDARD_THRESHOLDS,
} from './k6.config.js';

/**
 * NORMAL LOAD TEST — Baseline production traffic
 * VUs: 50 | Duration: 10 minutes
 * Simulates typical day: 70% reads, 20% list, 10% writes
 */

// Custom metrics
const orderCreateDuration = new Trend('order_create_duration', true);
const orderListDuration = new Trend('order_list_duration', true);
const dashboardDuration = new Trend('dashboard_duration', true);
const orderDetailDuration = new Trend('order_detail_duration', true);
const errorRate = new Rate('business_errors');
const ordersCreated = new Counter('orders_created');

export const options = {
  stages: [
    { duration: '1m', target: 25 },    // Ramp up
    { duration: '8m', target: 50 },    // Sustained load
    { duration: '1m', target: 0 },     // Ramp down
  ],
  thresholds: {
    ...STANDARD_THRESHOLDS,
    order_create_duration: ['p(95)<300'],
    order_list_duration: ['p(95)<150'],
    dashboard_duration: ['p(95)<200'],
    order_detail_duration: ['p(95)<150'],
    business_errors: ['rate<0.005'],
  },
  tags: { test_type: 'normal' },
};

// Test data pool
const ORDER_IDS = [];
const EVENT_TYPES = ['corporate', 'social', 'wedding', 'conference', 'festival'];

export default function () {
  const scenario = weightedRandom([
    { weight: 35, fn: listOrders },
    { weight: 25, fn: getOrderDetail },
    { weight: 15, fn: createOrder },
    { weight: 10, fn: adminDashboard },
    { weight: 5, fn: listQuotations },
    { weight: 5, fn: notificationStats },
    { weight: 5, fn: healthCheck },
  ]);

  scenario();
  sleep(randomBetween(0.5, 2));
}

function listOrders() {
  group('List Orders', () => {
    const page = Math.floor(Math.random() * 5) + 1;
    const status = Math.random() > 0.5
      ? EVENT_TYPES[Math.floor(Math.random() * EVENT_TYPES.length)]
      : '';

    const url = `${API_URL}/orders?page=${page}&limit=20${status ? `&status=${status}` : ''}`;
    const res = http.get(url, { headers: authHeaders('client') });

    orderListDuration.add(res.timings.duration);
    check(res, checkResponse(res, 'list-orders'));

    // Collect order IDs for detail tests
    try {
      const body = JSON.parse(res.body);
      if (body.data?.orders) {
        for (const order of body.data.orders.slice(0, 3)) {
          if (ORDER_IDS.length < 100) ORDER_IDS.push(order.id);
        }
      }
    } catch { /* ignore */ }
  });
}

function getOrderDetail() {
  group('Order Detail', () => {
    if (ORDER_IDS.length === 0) {
      listOrders(); // Seed IDs first
      return;
    }

    const orderId = ORDER_IDS[Math.floor(Math.random() * ORDER_IDS.length)];
    const res = http.get(`${API_URL}/orders/${orderId}`, {
      headers: authHeaders('client'),
    });

    orderDetailDuration.add(res.timings.duration);

    const checks = checkResponse(res, 'order-detail');
    if (res.status === 404) {
      checks['order-detail: found'] = false;
      errorRate.add(1);
    } else {
      check(res, checks);
      errorRate.add(0);
    }
  });
}

function createOrder() {
  group('Create Order', () => {
    const payload = JSON.stringify({
      title: `Load Test Event ${Date.now()}-${Math.random().toString(36).slice(2)}`,
      description: 'Created during load testing',
      eventType: EVENT_TYPES[Math.floor(Math.random() * EVENT_TYPES.length)],
      eventDate: randomFutureDate(),
      estimatedBudget: {
        amount: Math.floor(Math.random() * 200000) + 10000,
        currency: 'MXN',
      },
      guestCount: Math.floor(Math.random() * 500) + 10,
      urgency: ['low', 'normal', 'high'][Math.floor(Math.random() * 3)],
    });

    const res = http.post(`${API_URL}/orders`, payload, {
      headers: authHeaders('client'),
    });

    orderCreateDuration.add(res.timings.duration);

    if (res.status === 201) {
      ordersCreated.add(1);
      try {
        const body = JSON.parse(res.body);
        if (body.data?.orderId && ORDER_IDS.length < 200) {
          ORDER_IDS.push(body.data.orderId);
        }
      } catch { /* ignore */ }
    }

    check(res, {
      'create-order: status 201': res.status === 201,
    });
  });
}

function adminDashboard() {
  group('Admin Dashboard', () => {
    const res = http.get(`${API_URL}/admin/dashboard`, {
      headers: authHeaders('admin'),
    });

    dashboardDuration.add(res.timings.duration);
    check(res, checkResponse(res, 'admin-dashboard'));
  });
}

function listQuotations() {
  group('List Quotations', () => {
    if (ORDER_IDS.length === 0) return;

    const orderId = ORDER_IDS[Math.floor(Math.random() * ORDER_IDS.length)];
    const res = http.get(`${API_URL}/orders/${orderId}/quotations`, {
      headers: authHeaders('admin'),
    });

    check(res, checkResponse(res, 'list-quotations'));
  });
}

function notificationStats() {
  group('Notification Stats', () => {
    const res = http.get(`${API_URL}/admin/notifications/stats?hours=24`, {
      headers: authHeaders('admin'),
    });

    check(res, checkResponse(res, 'notification-stats'));
  });
}

function healthCheck() {
  group('Health Check', () => {
    const res = http.get(`${API_URL}/health`);
    check(res, { 'health: status 200': res.status === 200 });
  });
}

// ── Helpers ──

function weightedRandom(items) {
  const totalWeight = items.reduce((sum, i) => sum + i.weight, 0);
  let random = Math.random() * totalWeight;

  for (const item of items) {
    random -= item.weight;
    if (random <= 0) return item.fn;
  }

  return items[items.length - 1].fn;
}

function randomBetween(min, max) {
  return min + Math.random() * (max - min);
}

function randomFutureDate() {
  const date = new Date();
  date.setDate(date.getDate() + Math.floor(Math.random() * 365) + 30);
  return date.toISOString();
}

import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Trend, Rate } from 'k6/metrics';
import { API_URL, authHeaders, checkResponse } from './k6.config.js';

/**
 * PEAK LOAD TEST — Simulates traffic spike (e.g. marketing campaign)
 * VUs: 200 | Duration: 5 minutes
 * Purpose: Can we handle 4x normal traffic?
 */

const peakLatency = new Trend('peak_latency', true);
const peakErrors = new Rate('peak_errors');

export const options = {
  stages: [
    { duration: '30s', target: 100 },   // Fast ramp
    { duration: '3m', target: 200 },     // Peak sustained
    { duration: '1m', target: 50 },      // Recovery
    { duration: '30s', target: 0 },      // Cooldown
  ],
  thresholds: {
    http_req_duration: ['p(95)<300', 'p(99)<800'],
    http_req_failed: ['rate<0.005'],    // < 0.5% errors allowed under peak
    peak_errors: ['rate<0.01'],
  },
  tags: { test_type: 'peak' },
};

const ORDER_IDS = [];

export default function () {
  const actions = [
    { weight: 40, fn: readOrder },
    { weight: 30, fn: listOrders },
    { weight: 15, fn: createOrder },
    { weight: 10, fn: dashboard },
    { weight: 5, fn: health },
  ];

  const totalWeight = actions.reduce((s, a) => s + a.weight, 0);
  let r = Math.random() * totalWeight;
  for (const action of actions) {
    r -= action.weight;
    if (r <= 0) { action.fn(); break; }
  }

  sleep(Math.random() * 1.5 + 0.3);
}

function listOrders() {
  group('Peak: List Orders', () => {
    const res = http.get(`${API_URL}/orders?page=1&limit=20`, {
      headers: authHeaders('client'),
    });
    peakLatency.add(res.timings.duration);

    const ok = check(res, checkResponse(res, 'peak-list'));
    if (!ok) peakErrors.add(1);
    else peakErrors.add(0);

    try {
      const body = JSON.parse(res.body);
      if (body.data?.orders) {
        for (const o of body.data.orders.slice(0, 2)) {
          if (ORDER_IDS.length < 50) ORDER_IDS.push(o.id);
        }
      }
    } catch { /* ignore */ }
  });
}

function readOrder() {
  group('Peak: Read Order', () => {
    if (ORDER_IDS.length === 0) { listOrders(); return; }

    const id = ORDER_IDS[Math.floor(Math.random() * ORDER_IDS.length)];
    const res = http.get(`${API_URL}/orders/${id}`, {
      headers: authHeaders('client'),
    });
    peakLatency.add(res.timings.duration);

    if (res.status !== 200 && res.status !== 404) peakErrors.add(1);
    else peakErrors.add(0);
  });
}

function createOrder() {
  group('Peak: Create Order', () => {
    const payload = JSON.stringify({
      title: `Peak Test ${Date.now()}`,
      eventType: 'corporate',
      eventDate: '2026-12-15T10:00:00Z',
      guestCount: 100,
    });

    const res = http.post(`${API_URL}/orders`, payload, {
      headers: authHeaders('client'),
    });
    peakLatency.add(res.timings.duration);

    if (res.status !== 201) peakErrors.add(1);
    else {
      peakErrors.add(0);
      try {
        const body = JSON.parse(res.body);
        if (body.data?.orderId && ORDER_IDS.length < 100) {
          ORDER_IDS.push(body.data.orderId);
        }
      } catch { /* ignore */ }
    }
  });
}

function dashboard() {
  group('Peak: Dashboard', () => {
    const res = http.get(`${API_URL}/admin/dashboard`, {
      headers: authHeaders('admin'),
    });
    peakLatency.add(res.timings.duration);

    if (res.status !== 200) peakErrors.add(1);
    else peakErrors.add(0);
  });
}

function health() {
  group('Peak: Health', () => {
    const res = http.get(`${API_URL}/health`);
    check(res, { 'health ok': res.status === 200 });
  });
}

import http from 'k6/http';
